	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.bOMItemSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for BOMItem : " + successValue.getBOMItemId());
							  if (successValue.getBOMItemId().equals(bOMItemId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfBOMItemList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("BOMItem test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on bOMItem consumed")
					);
			subscriber.bOMItemSubscribe( bOMItemId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for BOMItem : " + successValue.getBOMItemId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfBOMItemList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on bOMItem for bOMItemId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a BOMItem. 
	 */
	protected BOMItem read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created BOMItem" );

		BOMItem entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read BOMItem with primary key" );
		msg.append( bOMItemId );
		
		BOMItemFetchOneSummary fetchOneSummary = new BOMItemFetchOneSummary( bOMItemId );

		try {
			entity = BOMItemService.getBOMItemInstance().getBOMItem( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found BOMItem " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a BOMItem.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a BOMItem." );

		StringBuilder msg = new StringBuilder( "Failed to update a BOMItem : " );        
		BOMItem entity = read();
		UpdateBOMItemCommand command = generateUpdateCommand();
		command.setBOMItemId(entity.getBOMItemId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created BOMItem." );

			// for use later on...
			bOMItemId = entity.getBOMItemId();

			BOMItemService proxy = BOMItemService.getBOMItemInstance();  

			proxy.updateBOMItem( command ).get();

			LOGGER.info( "-- Successfully saved BOMItem - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + bOMItemId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a BOMItem.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created BOMItem." );

		BOMItem entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read BOMItem with id " + bOMItemId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read BOMItem with id " + bOMItemId );

			throw e;
		}

		try{
			BOMItemService.getBOMItemInstance().delete( new DeleteBOMItemCommand( entity.getBOMItemId() ) ).get();
			LOGGER.info( "-- Successfully deleted BOMItem with id " + bOMItemId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete BOMItem with id " + bOMItemId );

			throw e;
		}
	}

	/**
	 * get all BOMItems.
	 */
	protected List<BOMItem> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of BOMItems:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all BOMItem : " );        
		List<BOMItem> collection  = new ArrayList<>();

		try {
			// call the static get method on the BOMItemService
			collection = BOMItemService.getBOMItemInstance().getAllBOMItem();
			assertNotNull( collection, "An Empty collection of BOMItem was incorrectly returned.");
			
			// Now print out the values
			BOMItem entity = null;            
			Iterator<BOMItem> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getBOMItemId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

